<?php
require_once __DIR__ . '/../_common.php';api_require_role('fo');
function foCheckoutItems(mysqli $conn,int $id):array{$s=$conn->prepare('SELECT d.id_produk,p.nama_produk,d.jumlah,d.harga_satuan,d.subtotal FROM detail_transaksi d LEFT JOIN produk p ON p.id_produk=d.id_produk WHERE d.id_transaksi=? ORDER BY d.id_detail');$s->bind_param('i',$id);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();return $rows;}
function foCheckoutFile(array $file,int $id):string{if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)throw new InvalidArgumentException('File bukti pembayaran wajib dipilih.');if(($file['size']??0)<1||$file['size']>5*1024*1024)throw new InvalidArgumentException('File bukti maksimal 5 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$types=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','application/pdf'=>'pdf'];if(!isset($types[$mime]))throw new InvalidArgumentException('Bukti harus JPG, PNG, WEBP, atau PDF.');$folder=dirname(__DIR__,2).DIRECTORY_SEPARATOR.'uploads'.DIRECTORY_SEPARATOR.'bukti-pembayaran';if(!is_dir($folder)&&!mkdir($folder,0755,true)&&!is_dir($folder))throw new RuntimeException('Folder bukti pembayaran tidak bisa dibuat.');$name='fo-'.$id.'-'.bin2hex(random_bytes(8)).'.'.$types[$mime];if(!move_uploaded_file($file['tmp_name'],$folder.DIRECTORY_SEPARATOR.$name))throw new RuntimeException('File gagal disimpan.');return 'uploads/bukti-pembayaran/'.$name;}
try{$m=api_allow_methods(['GET','POST','PUT']);$foId=(int)$_SESSION['id_akun'];
if($m==='GET'){$id=api_int($_GET['id_transaksi']??null,'id_transaksi');$s=$conn->prepare('SELECT id_transaksi,id_fo,nama_customer,tanggal_masuk,tanggal_selesai,total_harga,id_voucher,kode_voucher,diskon,total_bayar,metode_pembayaran,status_pembayaran,status_pesanan,bukti_pembayaran FROM transaksi WHERE id_transaksi=? AND id_fo=? AND id_user IS NULL');$s->bind_param('ii',$id,$foId);$s->execute();$row=api_one($s);$s->close();if(!$row)throw new OutOfBoundsException('Transaksi offline tidak ditemukan.');$row['detail']=foCheckoutItems($conn,$id);api_reply(200,true,'Detail transaksi offline berhasil diambil.',$row);}
if($m==='POST'&&($_POST['action']??'')==='upload_bukti'){$id=api_int($_POST['id_transaksi']??null,'id_transaksi');$path=foCheckoutFile($_FILES['bukti_transaksi']??[],$id);$s=$conn->prepare("UPDATE transaksi SET bukti_pembayaran=?,updated_at=NOW() WHERE id_transaksi=? AND id_fo=? AND id_user IS NULL AND metode_pembayaran='qris' AND status_pembayaran='menunggu_verifikasi'");$s->bind_param('sii',$path,$id,$foId);$s->execute();$changed=$s->affected_rows;$s->close();if(!$changed){@unlink(dirname(__DIR__,2).DIRECTORY_SEPARATOR.str_replace('/',DIRECTORY_SEPARATOR,$path));throw new DomainException('Transaksi QRIS tidak ditemukan atau sudah tidak menunggu bukti.');}api_reply(200,true,'Bukti pembayaran offline tersimpan.',['id_transaksi'=>$id,'bukti_pembayaran'=>$path]);}
$b=api_body();if($m==='POST'){$items=$b['items']??null;if(!is_array($items)||count($items)<1)throw new InvalidArgumentException('items harus berisi minimal satu produk.');$method=strtolower(api_string($b['metode_pembayaran']??null,'metode_pembayaran',10));if(!in_array($method,['cash','qris'],true))throw new InvalidArgumentException('metode_pembayaran harus cash atau qris.');$customer=api_string($b['nama_customer']??'Pelanggan Toko','nama_customer',100);$voucherCode=isset($b['kode_voucher'])?strtoupper(trim((string)$b['kode_voucher'])):null;if($voucherCode==='')$voucherCode=null;
$conn->begin_transaction();try{$lines=[];$subtotal=0.0;foreach($items as $line){if(!is_array($line))throw new InvalidArgumentException('Format item tidak valid.');$pid=api_int($line['id_produk']??null,'id_produk');$qty=api_int($line['jumlah']??null,'jumlah');$s=$conn->prepare('SELECT id_produk,nama_produk,harga,stok,status_produk FROM produk WHERE id_produk=? FOR UPDATE');$s->bind_param('i',$pid);$s->execute();$p=api_one($s);$s->close();if(!$p||$p['status_produk']!=='aktif')throw new DomainException('Produk tidak ditemukan atau tidak aktif: '.$pid);if($qty>(int)$p['stok'])throw new DomainException('Stok produk '.$p['nama_produk'].' tidak mencukupi.');$price=(float)$p['harga'];$lineTotal=round($price*$qty,2);$subtotal+=$lineTotal;$lines[]=['id_produk'=>$pid,'jumlah'=>$qty,'harga'=>$price,'subtotal'=>$lineTotal];}
$voucherId=null;$voucherStored=null;$discount=0.0;if($voucherCode){$s=$conn->prepare("SELECT id_voucher,kode_voucher,jenis_diskon,nilai_diskon,minimal_belanja FROM voucher WHERE kode_voucher=? AND status_voucher='aktif' FOR UPDATE");$s->bind_param('s',$voucherCode);$s->execute();$v=api_one($s);$s->close();if(!$v)throw new DomainException('Voucher tidak ditemukan atau tidak aktif.');if($subtotal<(float)$v['minimal_belanja'])throw new DomainException('Minimal belanja voucher belum terpenuhi.');$amount=(float)$v['nilai_diskon'];$discount=$v['jenis_diskon']==='persen'?$subtotal*$amount/100:$amount;$discount=min($subtotal,round($discount,2));$voucherId=(int)$v['id_voucher'];$voucherStored=$v['kode_voucher'];}
$total=max(0,round($subtotal-$discount,2));$payment=$method==='cash'?'berhasil':'menunggu_verifikasi';$order=$method==='cash'?'selesai':'menunggu_verifikasi';$foId=(int)$_SESSION['id_akun'];$s=$conn->prepare('INSERT INTO transaksi(id_user,nama_customer,id_fo,tanggal_masuk,tanggal_selesai,total_harga,id_voucher,kode_voucher,diskon,total_bayar,metode_pembayaran,status_pembayaran,status_pesanan) VALUES(NULL,?,?,NOW(),'.($method==='cash'?'NOW()':'NULL').',?,?,?,?,?,?,?,?)');$s->bind_param('sidisddsss',$customer,$foId,$subtotal,$voucherId,$voucherStored,$discount,$total,$method,$payment,$order);$s->execute();$id=(int)$conn->insert_id;$s->close();$d=$conn->prepare('INSERT INTO detail_transaksi(id_transaksi,id_produk,jumlah,harga_satuan,subtotal) VALUES(?,?,?,?,?)');foreach($lines as $line){$pid=$line['id_produk'];$qty=$line['jumlah'];$price=$line['harga'];$lineTotal=$line['subtotal'];$d->bind_param('iiidd',$id,$pid,$qty,$price,$lineTotal);$d->execute();}$d->close();$conn->commit();}catch(Throwable $e){$conn->rollback();throw $e;}api_reply(201,true,'Transaksi offline berhasil dibuat.',['id_transaksi'=>$id,'subtotal'=>$subtotal,'id_voucher'=>$voucherId,'kode_voucher'=>$voucherStored,'diskon'=>$discount,'total_pembayaran'=>$total,'metode_pembayaran'=>$method,'status_pembayaran'=>$payment,'status_pesanan'=>$order]);}
$id=api_int($b['id_transaksi']??null,'id_transaksi');$action=$b['action']??'';if(!in_array($action,['verifikasi_qris','tolak_qris'],true))throw new InvalidArgumentException('action harus verifikasi_qris atau tolak_qris.');$conn->begin_transaction();try{$s=$conn->prepare('SELECT status_pembayaran,status_pesanan,metode_pembayaran,bukti_pembayaran FROM transaksi WHERE id_transaksi=? AND id_fo=? AND id_user IS NULL FOR UPDATE');$s->bind_param('ii',$id,$foId);$s->execute();$row=api_one($s);$s->close();if(!$row)throw new OutOfBoundsException('Transaksi offline tidak ditemukan.');if($row['metode_pembayaran']!=='qris'||$row['status_pembayaran']!=='menunggu_verifikasi')throw new LogicException('Transaksi bukan QRIS yang menunggu verifikasi.');if($action==='verifikasi_qris'&&!$row['bukti_pembayaran'])throw new DomainException('Bukti pembayaran QRIS belum diunggah.');if($action==='verifikasi_qris')$s=$conn->prepare("UPDATE transaksi SET status_pembayaran='berhasil',status_pesanan='selesai',tanggal_selesai=NOW(),updated_at=NOW() WHERE id_transaksi=?");else $s=$conn->prepare("UPDATE transaksi SET status_pembayaran='gagal',status_pesanan='ditolak',updated_at=NOW() WHERE id_transaksi=?");$s->bind_param('i',$id);$s->execute();$s->close();$conn->commit();}catch(Throwable $e){$conn->rollback();throw $e;}api_reply(200,true,'Status pembayaran QRIS diperbarui.',['id_transaksi'=>$id,'status_pembayaran'=>$action==='verifikasi_qris'?'berhasil':'gagal','status_pesanan'=>$action==='verifikasi_qris'?'selesai':'ditolak']);
}catch(Throwable $e){api_db_error($e);}